export function migrateConfig(loadedConfig: any, version: number = DeviceConfig.Version) {
	if (loadedConfig._version === version) return
	if (loadedConfig._version == null || loadedConfig._version < 3) migrateConfigV2to3(loadedConfig)
	loadedConfig._version = version
}

/**
